{"id":"8aaf481f-c6e4-4fb1-a8dc-121fb8940598","name":"Chatbot Gemini con API de Criptomonedas y Finanzas","timestamp":1752522123071,"messages":[{"role":"user","content":[{"type":"text","text":"
